-- Demo purchase requests and projects (20 each). Safe to run again: existing references are skipped.
-- Remove them with the DELETE block at the end.
DO $$ BEGIN



IF (SELECT count(*) FROM users WHERE email IN ('bidder011@demo.sjbac.test', 'bidder035@demo.sjbac.test', 'bidder048@demo.sjbac.test', 'bidder049@demo.sjbac.test', 'bidder057@demo.sjbac.test', 'bidder073@demo.sjbac.test', 'bidder076@demo.sjbac.test', 'bidder086@demo.sjbac.test', 'bidder021@demo.sjbac.test', 'bidder037@demo.sjbac.test', 'bidder051@demo.sjbac.test', 'bidder066@demo.sjbac.test', 'bidder082@demo.sjbac.test', 'bidder087@demo.sjbac.test', 'bidder043@demo.sjbac.test', 'bidder054@demo.sjbac.test', 'bidder056@demo.sjbac.test', 'bidder099@demo.sjbac.test', 'bidder005@demo.sjbac.test', 'bidder008@demo.sjbac.test', 'bidder013@demo.sjbac.test', 'bidder016@demo.sjbac.test', 'bidder030@demo.sjbac.test', 'bidder068@demo.sjbac.test', 'bidder085@demo.sjbac.test', 'bidder098@demo.sjbac.test', 'bidder024@demo.sjbac.test', 'bidder039@demo.sjbac.test', 'bidder053@demo.sjbac.test', 'bidder081@demo.sjbac.test', 'bidder040@demo.sjbac.test', 'bidder044@demo.sjbac.test', 'bidder052@demo.sjbac.test', 'bidder009@demo.sjbac.test', 'bidder014@demo.sjbac.test', 'bidder020@demo.sjbac.test', 'bidder075@demo.sjbac.test', 'bidder097@demo.sjbac.test', 'bidder010@demo.sjbac.test', 'bidder019@demo.sjbac.test', 'bidder061@demo.sjbac.test', 'bidder027@demo.sjbac.test', 'bidder031@demo.sjbac.test', 'bidder042@demo.sjbac.test', 'bidder088@demo.sjbac.test', 'bidder034@demo.sjbac.test', 'bidder058@demo.sjbac.test', 'bidder074@demo.sjbac.test', 'bidder002@demo.sjbac.test', 'bidder093@demo.sjbac.test', 'bidder046@demo.sjbac.test', 'bidder062@demo.sjbac.test', 'bidder072@demo.sjbac.test')) = 53 THEN
UPDATE awards SET certificate_number = 'BAC-AWD-' || to_char(created_at, 'YYYY') || '-' || lpad(id::text, 6, '0') WHERE certificate_number IS NULL AND project_id IN (SELECT id FROM projects WHERE reference_no LIKE 'SJ-BAC-2026-%-D__');
ELSE
RAISE NOTICE 'The 30 awarded projects were not added: the demo bidder accounts are not all in the database. Load the demo accounts first, then run this again.';
END IF;

UPDATE projects SET bidding_fee_mode = 'schedule', bidding_documents_fee = CASE WHEN budget <= 500000 THEN 500 WHEN budget <= 1000000 THEN 1000 WHEN budget <= 5000000 THEN 5000 WHEN budget <= 10000000 THEN 10000 WHEN budget <= 50000000 THEN 25000 WHEN budget <= 500000000 THEN 50000 ELSE 75000 END WHERE reference_no LIKE 'SJ-BAC-2026-%-D__' AND bidding_fee_mode IS NULL;

END $$;

